def sha(data: bytes) -> str:
    return hashlib.sha256(data).hexdigest()


def normalized(raw: bytes) -> str:
    return raw.decode('utf-8-sig').replace('\r\n', '\n')


def target_bytes(raw: bytes, source: str) -> bytes:
    ending = '\r\n' if b'\r\n' in raw else '\n'
    new = source.replace('\n', ending).encode('utf-8')
    return (codecs.BOM_UTF8 if raw.startswith(codecs.BOM_UTF8) else b'') + new


def safe_target(project: Path, relative: str) -> Path:
    if relative not in PAYLOAD:
        raise ValueError('Unexpected manifest path')
    target=project / relative
    for path in (target, *target.parents):
        if path == project:
            break
        if path.is_symlink():
            raise ValueError('Symlinked target is not supported')
    if not target.is_file() or not target.resolve().is_relative_to(project):
        raise ValueError('Missing or outside-project target: ' + relative)
    return target


def atomic_write(path: Path, data: bytes) -> None:
    temp=None
    try:
        with tempfile.NamedTemporaryFile(dir=path.parent, prefix='.agent-diagnostics-', delete=False) as stream:
            temp=Path(stream.name)
            stream.write(data)
            stream.flush()
            os.fsync(stream.fileno())
        os.replace(temp, path)
        temp=None
    finally:
        if temp is not None:
            temp.unlink(missing_ok=True)


def plan(project: Path):
    changes=[]
    for relative,item in PAYLOAD.items():
        if item['optional'] and not (project / relative).is_file():
            continue
        target=safe_target(project, relative)
        before=target.read_bytes()
        actual=sha(normalized(before).encode('utf-8'))
        if actual == item['after_sha256']:
            print('[OK] Already installed:', relative)
            continue
        if actual != item['before_sha256']:
            if item['optional']:
                print('[SKIP] Optional diagnostic script has local changes:', relative)
                continue
            raise ValueError('Source differs from Agent v1; no files written: ' + relative)
        after=target_bytes(before,item['content'])
        if relative.endswith('.py'):
            ast.parse(normalized(after), filename=relative)
        changes.append((relative, target, before, after))
    return changes


def apply_patch(project: Path, apply: bool) -> Path | None:
    changes=plan(project)  # Preflight all files before writing ANY source file.
    if not changes:
        print('[OK] Runtime diagnostics 1.1.0 is already installed.')
        return None
    for relative,_,_,_ in changes:
        print('[PLAN]',relative)
    if not apply:
        print('[PREVIEW] No files changed. Stop the backend, then run with --apply.')
        return None
    stamp=datetime.now(timezone.utc).strftime('%Y%m%dT%H%M%S%fZ')
    backup=project / '.agent-runtime-diagnostics-backups' / stamp
    backup.mkdir(parents=True,exist_ok=False)
    manifest={'version':'1.1.0','files':[]}
    for relative,target,before,after in changes:
        copy=backup / relative
        copy.parent.mkdir(parents=True,exist_ok=True)
        copy.write_bytes(before)
        manifest['files'].append({'path':relative,'before_sha256':sha(before),'after_sha256':sha(after)})
    (backup / 'manifest.json').write_text(json.dumps(manifest,indent=2),encoding='utf-8')
    written=[]
    try:
        for relative,target,before,after in changes:
            if target.read_bytes()!=before:
                raise ValueError('Source changed during installation: '+relative)
            atomic_write(target,after)
            written.append((target,before))
    except Exception:
        for target,before in reversed(written):
            atomic_write(target,before)
        raise
    print('[OK] Installed runtime diagnostics 1.1.0.')
    print('[BACKUP]',backup)
    print('[UNCHANGED] .env, HTTP allowlist, timeouts, token limits, business DB, confirmation gates.')
    print('[NEXT] Restart backend. Ctrl+F5 in browser. Create a NEW Agent session; enter 查询科室.')
    print('[NEXT] Share only the new [AgentRuntime] summary; never share keys or session tokens.')
    return backup


def rollback(project: Path, backup: Path, apply: bool) -> None:
    backup=backup.resolve()
    root=(project / '.agent-runtime-diagnostics-backups').resolve()
    if not backup.is_relative_to(root) or backup==root:
        raise ValueError('Backup must be under this project diagnostics backup directory')
    manifest=json.loads((backup / 'manifest.json').read_text(encoding='utf-8'))
    changes=[]
    seen=set()
    for item in manifest['files']:
        relative=item['path']
        if relative in seen:
            raise ValueError('Duplicate backup target')
        seen.add(relative)
        target=safe_target(project,relative)
        copy=backup / relative
        if not copy.resolve().is_relative_to(backup) or copy.is_symlink():
            raise ValueError('Invalid backup target')
        old=copy.read_bytes()
        current=target.read_bytes()
        if sha(old)!=item['before_sha256'] or sha(current)!=item['after_sha256']:
            raise ValueError('Backup/current source changed; refusing rollback: '+relative)
        changes.append((target,old,current))
    if not apply:
        print('[PREVIEW] Rollback validated; use --apply to restore source. No DB changes.')
        return
    written=[]
    try:
        for target,old,current in changes:
            if target.read_bytes()!=current:
                raise ValueError('Concurrent source modification')
            atomic_write(target,old)
            written.append((target,current))
    except Exception:
        for target,current in reversed(written):
            atomic_write(target,current)
        raise
    print('[OK] Source restored. .env and databases were not changed. Restart backend.')


def main(argv=None) -> int:
    parser=argparse.ArgumentParser(description=__doc__)
    parser.add_argument('--project',type=Path,default=Path.cwd())
    parser.add_argument('--apply',action='store_true')
    parser.add_argument('--rollback',type=Path)
    args=parser.parse_args(argv)
    project=args.project.resolve()
    try:
        if args.rollback:
            rollback(project,args.rollback,args.apply)
        else:
            apply_patch(project,args.apply)
    except Exception as exc:
        # No configuration import, network call, or user database access occurs here.
        if isinstance(exc,ValueError):
            print('[ERROR]',str(exc))
        else:
            print('[ERROR] Installation stopped:',type(exc).__name__)
        return 1
    return 0


if __name__=='__main__':
    raise SystemExit(main())
